mapper.select:
SELECT * FROM CHANNEL_INBOUND_INBOX WHERE TENANT_ID=#{tenantId} AND SOURCE_NAME=#{sourceName}
 AND ((STATUS_CODE='PENDING' AND NEXT_ATTEMPT_AT<=#{nextAttemptAt})
      OR (STATUS_CODE='RUNNING' AND LEASE_UNTIL<=#{leaseUntil}))
ORDER BY CREATED_AT, INBOX_ID LIMIT #{limit}

mapper.update:
UPDATE CHANNEL_INBOUND_INBOX SET LEASE_UNTIL=#{leaseUntil}, UPDATED_AT=#{updatedAt}
WHERE INBOX_ID=#{inboxId} AND TENANT_ID=#{tenantId} AND STATUS_CODE='RUNNING'
  AND LEASE_OWNER=#{leaseOwner} AND LEASE_EPOCH=#{leaseEpoch} AND LEASE_UNTIL>#{leaseUntil2}
